* >Natural Source Code: POENTR
* PROGRAM: POENTR - PURCHASE ORDER ENTRY (ONLINE)
* DESCRIPTION: INTERACTIVE PO CREATION SCREEN
*              SUPPLIER SELECTION -> LINE ITEMS -> APPROVAL
* LIBRARY: RETAILCORE
* ADABAS FILES: 131 (PO-HEADER), 132 (PO-LINE)
* CREATED: 2001-09-15  A. GARCIA
* MODIFIED: 2007-03-10 - ADDED AUTO-APPROVAL
* MODIFIED: 2014-08-22 - ADDED REPLENISHMENT LINK
* MODIFIED: 2020-05-15 - ADDED MULTI-WAREHOUSE
* -------------------------------------------------------
DEFINE DATA
LOCAL USING SUPP-COPY
LOCAL USING PROD-COPY
LOCAL USING COMMON-COPY
*
LOCAL
  1 #SCREEN-MSG           (A78)
  1 #USER-ID              (A8)
  1 #NEW-PO-ID            (N10)
  1 #PO-NUMBER            (A15)
  1 #LINE-IDX             (N3)
  1 #MAX-LINES            (N3)    INIT <50>
  1 #SUPP-FOUND           (A1)
  1 #SUPP-MSG             (A60)
  1 #VALID-FLAG           (A1)
  1 #ERROR-MSG            (A60)
  1 #ORD-STR              (A15)
  1 #AUTO-APPROVE-LIMIT   (N11.2)  INIT <5000.00>
*
* PO LINE ARRAY
  1 #PO-LINES (50)
    2 #PL-PROD-ID         (N8)
    2 #PL-SKU             (A15)
    2 #PL-DESCRIPTION     (A60)
    2 #PL-QTY             (N6)
    2 #PL-UNIT-COST       (N9.2)
    2 #PL-LINE-TOTAL      (N11.2)
    2 #PL-WH-ID           (N4)
*
  1 #PO-SUBTOTAL          (N11.2)
  1 #PO-TAX               (N9.2)
  1 #PO-SHIPPING          (N9.2)
  1 #PO-TOTAL             (N11.2)
  1 #SUPP-LEAD-DAYS       (N3)
  1 #EXPECTED-DATE        (D)
  1 #CONFIG-VALUE         (A80)
  1 #CONFIG-NUM           (N11.2)
  1 #CONFIG-DATE          (D)
  1 #CONFIG-FLAG          (A1)
  1 #CONFIG-FOUND         (A1)
*
  1 POH-VIEW VIEW OF PO-HEADER-FILE
    2 POH-ID               (N10)
    2 POH-NUMBER           (A15)
    2 POH-SUPP-ID          (N8)
    2 POH-STATUS           (A2)
    2 POH-TYPE             (A2)
    2 POH-WH-ID            (N4)
    2 POH-DATE             (D)
    2 POH-EXPECTED-DATE    (D)
    2 POH-NUM-LINES        (N3)
    2 POH-SUBTOTAL         (N11.2)
    2 POH-TAX-AMT          (N9.2)
    2 POH-SHIPPING-AMT     (N9.2)
    2 POH-TOTAL-AMT        (N11.2)
    2 POH-CURRENCY         (A3)
    2 POH-NOTES            (A200)
    2 POH-CREATED-BY       (A8)
    2 POH-CREATED-DATE     (D)
    2 POH-APPROVED-BY      (A8)
    2 POH-APPROVED-DATE    (D)
*
  1 POL-VIEW VIEW OF PO-LINE-FILE
    2 POL-PO-ID            (N10)
    2 POL-LINE-NO          (N3)
    2 POL-PROD-ID          (N8)
    2 POL-SKU              (A15)
    2 POL-DESCRIPTION      (A60)
    2 POL-QTY-ORDERED      (N6)
    2 POL-QTY-RECEIVED     (N6)
    2 POL-UNIT-COST        (N9.2)
    2 POL-LINE-TOTAL       (N11.2)
    2 POL-STATUS           (A2)
    2 POL-WH-ID            (N4)
END-DEFINE
*
MOVE *USER TO #USER-ID
*
* STEP 1: SUPPLIER SELECTION
INPUT (IP=ON) WITH TEXT #SCREEN-MSG
  / 'RETAILCORE - PURCHASE ORDER ENTRY' (I)
  / '==================================' (I)
  /
  / 'SUPPLIER ID  :' SUPP-ID (AD=MI)
  / 'WAREHOUSE ID :' SUPP-WH-ID (AD=MI)
  / 'PO TYPE      :' SUPP-PO-TYPE (AD=MI) '(ST=STANDARD EM=EMERGENCY RP=REPLEN)'
  /
  / 'PF3=CANCEL ENTER=CONTINUE'
*
IF *PF-KEY = 'PF3'
  ESCAPE ROUTINE
END-IF
*
* VALIDATE SUPPLIER
1 #SD-DATA
  2 #SD-ID    (N8)
  2 #SD-NAME  (A60)
  2 #SD-STATUS (A1)
  2 #SD-TYPE  (A2)
  2 #SD-CONTACT (A40)
  2 #SD-PHONE (A15)
  2 #SD-EMAIL (A60)
1 #SD-ADDR
  2 #AD-LINE1 (A40)
  2 #AD-LINE2 (A40)
  2 #AD-CITY  (A30)
  2 #AD-STATE (A2)
  2 #AD-ZIP   (A10)
  2 #AD-CTRY  (A3)
1 #SD-TERMS
  2 #TM-PAY   (A10)
  2 #TM-DAYS  (N3)
  2 #TM-DISC  (N5.2)
  2 #TM-DDAYS (N3)
  2 #TM-LEAD  (N3)
  2 #TM-MIN   (N9.2)
  2 #TM-FRGHT (A3)
  2 #TM-CURR  (A3)
1 #SD-PERF
  2 #PF-RATE  (N3)
  2 #PF-OT    (N5.2)
  2 #PF-QL    (N5.2)
  2 #PF-FL    (N5.2)
  2 #PF-POS   (N6)
  2 #PF-AMT   (N11.2)
  2 #PF-DATE  (D)
*
CALLNAT 'SUPPGET' SUPP-ID #SD-DATA #SD-ADDR #SD-TERMS #SD-PERF
  #SUPP-FOUND #SUPP-MSG
IF #SUPP-FOUND NE 'Y'
  MOVE #SUPP-MSG TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
IF #SD-STATUS NE 'A'
  MOVE 'SUPPLIER IS NOT ACTIVE' TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
MOVE #TM-LEAD TO #SUPP-LEAD-DAYS
*
* STEP 2: LINE ITEM ENTRY
RESET #PO-SUBTOTAL
RESET #LINE-IDX
*
REPEAT
  ADD 1 TO #LINE-IDX
  IF #LINE-IDX > #MAX-LINES
    ESCAPE BOTTOM
  END-IF
*
  INPUT (IP=ON) WITH TEXT #SCREEN-MSG
    / 'PO LINE' #LINE-IDX (AD=OI) 'SUPPLIER:' #SD-NAME (AD=OI)
    / 'PRODUCT ID :' #PO-LINES.#PL-PROD-ID(#LINE-IDX) (AD=MI)
    / 'SKU        :' #PO-LINES.#PL-SKU(#LINE-IDX) (AD=MI)
    / 'QUANTITY   :' #PO-LINES.#PL-QTY(#LINE-IDX) (AD=MI)
    / 'UNIT COST  :' #PO-LINES.#PL-UNIT-COST(#LINE-IDX) (AD=MI)
    / 'WAREHOUSE  :' #PO-LINES.#PL-WH-ID(#LINE-IDX) (AD=MI)
    / 'PF3=DONE ADDING LINES  ENTER=ADD LINE'
*
  IF *PF-KEY = 'PF3'
    SUBTRACT 1 FROM #LINE-IDX
    ESCAPE BOTTOM
  END-IF
*
  IF #PO-LINES.#PL-PROD-ID(#LINE-IDX) = 0
      AND #PO-LINES.#PL-SKU(#LINE-IDX) = ' '
    SUBTRACT 1 FROM #LINE-IDX
    ESCAPE BOTTOM
  END-IF
*
  * VALIDATE PRODUCT
  1 #PV-ID (N8)
  1 #PV-NAME (A60)
  1 #PV-STATUS (A1)
  1 #PV-PRICE (N9.2)
  1 #PV-TAX (A4)
  CALLNAT 'SKUVAL'
    #PO-LINES.#PL-SKU(#LINE-IDX) ' '
    #PV-ID #PV-NAME #PV-STATUS #PV-PRICE #PV-TAX
    #VALID-FLAG #ERROR-MSG
  IF #VALID-FLAG NE 'Y' AND #PO-LINES.#PL-PROD-ID(#LINE-IDX) = 0
    MOVE #ERROR-MSG TO #SCREEN-MSG
    SUBTRACT 1 FROM #LINE-IDX
    ESCAPE TOP
  END-IF
  IF #PO-LINES.#PL-PROD-ID(#LINE-IDX) = 0
    MOVE #PV-ID TO #PO-LINES.#PL-PROD-ID(#LINE-IDX)
  END-IF
  MOVE #PV-NAME TO #PO-LINES.#PL-DESCRIPTION(#LINE-IDX)
*
  * DEFAULT WAREHOUSE
  IF #PO-LINES.#PL-WH-ID(#LINE-IDX) = 0
    MOVE SUPP-WH-ID TO #PO-LINES.#PL-WH-ID(#LINE-IDX)
  END-IF
*
  * CALCULATE LINE TOTAL
  COMPUTE #PO-LINES.#PL-LINE-TOTAL(#LINE-IDX) =
    #PO-LINES.#PL-QTY(#LINE-IDX)
    * #PO-LINES.#PL-UNIT-COST(#LINE-IDX)
  ADD #PO-LINES.#PL-LINE-TOTAL(#LINE-IDX) TO #PO-SUBTOTAL
*
  COMPRESS 'LINE' #LINE-IDX 'ADDED:' #PV-NAME INTO #SCREEN-MSG
END-REPEAT
*
IF #LINE-IDX = 0
  MOVE 'NO PO LINES ENTERED' TO #SCREEN-MSG
  ESCAPE ROUTINE
END-IF
*
* CALCULATE TOTALS
COMPUTE #PO-TOTAL = #PO-SUBTOTAL + #PO-TAX + #PO-SHIPPING
*
* CALCULATE EXPECTED DATE
MOVE *DATX TO #EXPECTED-DATE
ADD #SUPP-LEAD-DAYS TO #EXPECTED-DATE (D)
*
* STEP 3: CONFIRMATION
INPUT (IP=ON)
  / 'PO CONFIRMATION' (I)
  / '================' (I)
  / 'SUPPLIER  :' #SD-NAME (AD=OI)
  / 'LINES     :' #LINE-IDX (AD=OI)
  / 'SUBTOTAL  :' #PO-SUBTOTAL (AD=OI)
  / 'TOTAL     :' #PO-TOTAL (AD=OI)
  / 'EXPECTED  :' #EXPECTED-DATE (AD=OI)
  /
  / 'PF3=CANCEL  ENTER=CREATE PO'
*
IF *PF-KEY = 'PF3'
  ESCAPE ROUTINE
END-IF
*
* STEP 4: CREATE PO
CALLNAT 'SEQNON' 'PO' #NEW-PO-ID
COMPRESS 'PO-' #NEW-PO-ID INTO #PO-NUMBER LEAVING NO SPACE
*
STORE POH-VIEW
  POH-ID            := #NEW-PO-ID
  POH-NUMBER        := #PO-NUMBER
  POH-SUPP-ID       := SUPP-ID
  POH-STATUS        := 'DR'
  POH-TYPE          := SUPP-PO-TYPE
  POH-WH-ID         := SUPP-WH-ID
  POH-DATE          := *DATX
  POH-EXPECTED-DATE := #EXPECTED-DATE
  POH-NUM-LINES     := #LINE-IDX
  POH-SUBTOTAL      := #PO-SUBTOTAL
  POH-TAX-AMT       := #PO-TAX
  POH-SHIPPING-AMT  := #PO-SHIPPING
  POH-TOTAL-AMT     := #PO-TOTAL
  POH-CURRENCY      := #TM-CURR
  POH-CREATED-BY    := #USER-ID
  POH-CREATED-DATE  := *DATX
END-STORE
*
* STORE PO LINES
1 #LN (N3)
FOR #LN = 1 TO #LINE-IDX
  STORE POL-VIEW
    POL-PO-ID        := #NEW-PO-ID
    POL-LINE-NO      := #LN
    POL-PROD-ID      := #PO-LINES.#PL-PROD-ID(#LN)
    POL-SKU          := #PO-LINES.#PL-SKU(#LN)
    POL-DESCRIPTION  := #PO-LINES.#PL-DESCRIPTION(#LN)
    POL-QTY-ORDERED  := #PO-LINES.#PL-QTY(#LN)
    POL-QTY-RECEIVED := 0
    POL-UNIT-COST    := #PO-LINES.#PL-UNIT-COST(#LN)
    POL-LINE-TOTAL   := #PO-LINES.#PL-LINE-TOTAL(#LN)
    POL-STATUS       := 'PN'
    POL-WH-ID        := #PO-LINES.#PL-WH-ID(#LN)
  END-STORE
END-FOR
*
END OF TRANSACTION
*
* AUTO-APPROVE IF BELOW LIMIT
CALLNAT 'CONFIGN' 'PO.AUTO.APPROVE.LIMIT'
  #CONFIG-VALUE #CONFIG-NUM #CONFIG-DATE #CONFIG-FLAG #CONFIG-FOUND
IF #CONFIG-FOUND = 'Y'
  MOVE #CONFIG-NUM TO #AUTO-APPROVE-LIMIT
END-IF
IF #PO-TOTAL <= #AUTO-APPROVE-LIMIT
  CALLNAT 'POVAL' #NEW-PO-ID 'APRV' #USER-ID
    #VALID-FLAG #ERROR-MSG
END-IF
*
* FORMAT PO AMOUNTS FOR DISPLAY
* CREATES CHAIN: POENTR -> FMTU
1 #PO-FMT-IN  (A80)
1 #PO-FMT-OUT (A132)
CALLNAT 'FMTU' 'CURR' #PO-FMT-IN #PO-TOTAL ' ' 0 #PO-FMT-OUT
CALLNAT 'FMTU' 'CURR' #PO-FMT-IN #PO-SUBTOTAL ' ' 0 #PO-FMT-OUT
*
* FORMAT EXPECTED DELIVERY DATE
* CREATES CHAIN: POENTR -> DATEU
1 #PO-DT-VALID  (A1)
1 #PO-DT-ERR    (A60)
1 #PO-DT-RESULT (D)
1 #PO-DT-STR    (A10)
1 #PO-DT-NUM    (N5)
CALLNAT 'DATEU' 'FMT' #EXPECTED-DATE #EXPECTED-DATE 0 #PO-DT-RESULT
  #PO-DT-STR #PO-DT-NUM #PO-DT-VALID #PO-DT-ERR
*
* CHECK IF EXPECTED DATE IS A BUSINESS DAY
CALLNAT 'DATEU' 'BUS' #EXPECTED-DATE #EXPECTED-DATE 0 #PO-DT-RESULT
  #PO-DT-STR #PO-DT-NUM #PO-DT-VALID #PO-DT-ERR
*
* VALIDATE SUPPLIER NAME FORMAT
* CREATES CHAIN: POENTR -> VALU
1 #PO-VL-FLAG (A1)
1 #PO-VL-MSG  (A60)
CALLNAT 'VALU' 'ALNM' #SD-NAME #PO-VL-FLAG #PO-VL-MSG
*
* CHECK INVENTORY FOR ALL PO LINES
* CREATES CHAIN: POENTR -> INVCHK -> PRODGET -> DATEU/CONFIGN
1 #PO-IC-RESULT
  2 #PO-ICR-OH    (N8)
  2 #PO-ICR-RES   (N8)
  2 #PO-ICR-ALLOC (N8)
  2 #PO-ICR-DMG   (N8)
  2 #PO-ICR-TRANS (N8)
  2 #PO-ICR-AVAIL (N8)
  2 #PO-ICR-SAFE  (N8)
  2 #PO-ICR-REORD (N8)
  2 #PO-ICR-BSAF  (A1)
  2 #PO-ICR-BREOD (A1)
  2 #PO-ICR-SUFF  (A1)
1 #PO-IC-RC     (N4)
1 #PO-IC-MSG    (A80)
1 #PO-IC-LN     (N3)
FOR #PO-IC-LN = 1 TO #LINE-IDX
  CALLNAT 'INVCHK' #PO-LINES.#PL-PROD-ID(#PO-IC-LN)
    #PO-LINES.#PL-SKU(#PO-IC-LN) 'W' 0 0
    #PO-IC-RESULT #PO-IC-RC #PO-IC-MSG
END-FOR
*
* RETRIEVE PRODUCT DATA FOR FIRST LINE ITEM
* CREATES CHAIN: POENTR -> PRODGET -> DATEU/CONFIGN
IF #LINE-IDX > 0
  1 #PO-PG-PROD-ID (N8)
  1 #PO-PG-SKU     (A15)
  1 #PO-PG-DATA
    2 #PO-PD-ID    (N8)
    2 #PO-PD-SKU   (A15)
    2 #PO-PD-ITEM  (A12)
    2 #PO-PD-NAME  (A60)
    2 #PO-PD-SHORT (A30)
    2 #PO-PD-LONG  (A200)
    2 #PO-PD-STAT  (A1)
    2 #PO-PD-TYPE  (A2)
    2 #PO-PD-BRAND (A30)
    2 #PO-PD-MFGR  (A40)
    2 #PO-PD-UPC   (A13)
  1 #PO-PG-CAT
    2 #PO-PC-DEPT  (A4)
    2 #PO-PC-CLS   (A4)
    2 #PO-PC-SUB   (A4)
    2 #PO-PC-PATH  (A60)
  1 #PO-PG-ATTR
    2 #PO-PA-COLOR (A20)
    2 #PO-PA-SIZE  (A10)
    2 #PO-PA-WGHT  (N7.3)
    2 #PO-PA-PRSH  (A1)
    2 #PO-PA-HAZD  (A1)
    2 #PO-PA-SEAS  (A1)
  1 #PO-PG-PRICE
    2 #PO-PP-COST  (N9.2)
    2 #PO-PP-PRICE (N9.2)
    2 #PO-PP-MSRP  (N9.2)
    2 #PO-PP-MIN   (N9.2)
    2 #PO-PP-TAX   (A4)
    2 #PO-PP-CURR  (A3)
  1 #PO-PG-LIFE
    2 #PO-PL-INT   (D)
    2 #PO-PL-DIS   (D)
    2 #PO-PL-CLR   (D)
    2 #PO-PL-LAST  (D)
  1 #PO-PG-FOUND (A1)
  1 #PO-PG-ERR   (A60)
  MOVE #PO-LINES.#PL-PROD-ID(1) TO #PO-PG-PROD-ID
  MOVE #PO-LINES.#PL-SKU(1) TO #PO-PG-SKU
  CALLNAT 'PRODGET' #PO-PG-PROD-ID #PO-PG-SKU #PO-PG-DATA #PO-PG-CAT
    #PO-PG-ATTR #PO-PG-PRICE #PO-PG-LIFE #PO-PG-FOUND #PO-PG-ERR
  IF #PO-PG-FOUND NE 'Y'
    CALLNAT 'LOGERR' 800 'PRODUCT NOT FOUND FOR PO LINE 1'
      'W' 'POENTR' #USER-ID
  END-IF
END-IF
*
* LOAD FREIGHT CONFIG
CALLNAT 'CONFIGN' 'PO.DEFAULT.FREIGHT.METHOD'
  #CONFIG-VALUE #CONFIG-NUM #CONFIG-DATE #CONFIG-FLAG #CONFIG-FOUND
*
* AUDIT
MOVE #NEW-PO-ID TO #ORD-STR
CALLNAT 'AUDITN' 'PO' #ORD-STR 'C' 'PO'
  ' ' #PO-NUMBER 'PURCHASE ORDER CREATED'
*
COMPRESS 'PO' #PO-NUMBER 'CREATED SUCCESSFULLY'
  INTO #SCREEN-MSG
*
END
